from __future__ import unicode_literals

from ..raml.xml import Xml
from .exceptions import NoSuchParameter
from ..raml.param import Param


class ListParam(Xml):

    ITEMS_PATH = '{*}item'
    ALL_PARAMS_PATH = ITEMS_PATH + '/' + '{*}p'
    PARAM_IN_ITEM_PATH = '{*}p[@name="{param_name}"]'
    PARAM_PATH = ITEMS_PATH + '/' + PARAM_IN_ITEM_PATH

    @property
    def name(self):
        """Name of this list parameter"""
        return self.xml.get('name')

    def remove(self):
        """Removes this list parameter from the parent managed object"""
        self._remove_element(self.xml)

    def find_param(self, param_name, param_value=None):
        """Returns the first parameter with given name and value"""
        node = self._find_param_node(param_name, param_value)
        return Param(node)

    def find_params(self, param_name):
        """Returns all parameters with given name"""
        return [Param(node) for node in self._find_all_param_nodes_by_name(param_name)]

    def _find_param_node(self, param_name, param_value):
        if param_value is None:
            node = self._find_param_node_by_name(param_name)
        else:
            node = self._find_param_node_by_name_and_value(param_name, param_value)
        return node

    def _find_param_node_by_name(self, param_name):
        return self._find_node_or_raise(self.PARAM_PATH, exception_class=NoSuchParameter, param_name=param_name)

    def _find_all_param_nodes_by_name(self, param_name):
        return self._find_all_nodes(self.PARAM_PATH, param_name=param_name)

    def _find_param_node_by_name_and_value(self, param_name, param_value):
        param_nodes = self._find_all_param_nodes_by_name(param_name)
        nodes_with_value = [node for node in param_nodes if node.text == param_value]
        if len(nodes_with_value) == 0:
            self._raise_on_node_not_found(NoSuchParameter, self.xml, self.PARAM_PATH, param_name=param_name, param_value=param_value)
        else:
            return nodes_with_value[0]

    def add_param(self, param_name, param_value):
        """Adds a parameter to this list. If a parameter with the same name exists, a duplicated parameter is added (to another <item>)"""
        self._ensure_has_items_node()
        self._ensure_has_items_node_without_param(param_name)
        items_node = self._find_items_node_without_param(param_name)
        param_element = self._add_element(items_node, 'p')
        param_element.set('name', param_name)
        param_element.text = str(param_value)
        return Param(param_element)

    def add_param_or_set_value_in_existing(self, param_name, param_value):
        """If a parameter named param_name exists, its value is set to param_value.
        Otherwise a new parameter is created with given name and value."""
        if self.has_param(param_name):
            param = self.find_param(param_name)
            param.value = param_value
            return param
        else:
            return self.add_param(param_name, param_value)

    def _find_items_node(self):
        return self._find_node(self.ITEMS_PATH)

    def _find_all_items_nodes(self):
        return self._find_all_nodes(self.ITEMS_PATH)

    def _find_items_node_without_param(self, param_name):
        items_nodes = self._find_all_items_nodes()
        param_in_item_path = self._parametrize_path(self.PARAM_IN_ITEM_PATH, param_name=param_name)
        nodes_without_param = [node for node in items_nodes if node.find(param_in_item_path) is None]
        return nodes_without_param[0] if len(nodes_without_param) > 0 else None

    def _ensure_has_items_node(self):
        if not self._has_items_node():
            self._fix_inner_indentation(self.xml)
            self._add_items_node()

    def _ensure_has_items_node_without_param(self, param_name):
        if self._find_items_node_without_param(param_name) is None:
            self._add_items_node()

    def _add_items_node(self):
        items_node = self._add_element(self.xml, 'item')
        self._fix_inner_indentation(items_node)

    def _has_items_node(self):
        return self._find_items_node() is not None

    def remove_param(self, param_name, param_value=None):
        """Removes the firs found parameter with given name and value"""
        node_to_remove = self._find_param_node(param_name, param_value)
        parent_items_node = node_to_remove.getparent()
        self._remove_element(node_to_remove)
        if self._is_empty(parent_items_node):
            self._remove_element(parent_items_node)
        if self._is_empty(self.xml):
            self.xml.text = None

    def has_param(self, param_name):
        """Returns true if this list parameter contains a parameter with given name, false otherwise"""
        try:
            self.find_param(param_name)
        except NoSuchParameter:
            return False
        else:
            return True

    def find_all_params(self):
        """Returns a list of objects representing all parameters"""
        return [Param(node) for node in self._find_all_nodes(self.ALL_PARAMS_PATH)]
